item.text:
**За премиум-скин внутри Telegram Mini App нужно принимать Telegram Stars (`XTR`).** Скин — цифровой товар, поэтому оплата за него через TON Connect не соответствует [правилам Telegram](https://core.telegram.org/bots/payments-stars). Цену в Stars нужно выбрать отдельно: фиксированного эквивалента «2 TON» нет.

Ниже пример на Node.js: фронтенд открывает счёт, сервер проверяет оплату и выдаёт скин.

Фронтенд — после подключения Telegram Web App SDK:

```html
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<button id="buy">Купить премиум-скин</button>

<script>
  const tg = window.Telegram.WebApp;
  tg.ready();

  document.querySelector("#buy").onclick = async () => {
    try {
      const response = await fetch("/api/skin/invoice", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ initData: tg.initData }),
      });

      if (!response.ok) throw new Error("Не удалось создать счёт");

      const { invoiceUrl } = await response.json();
      tg.openInvoice(invoiceUrl, status => {
        if (status === "paid") {
          // Обновите профиль с сервера: выдачу подтверждает бэкенд.
          console.log("Проверяем покупку на сервере");
        }
      });
    } catch (error) {
      tg.showAlert(error.message);
    }
  };
</script>
```

Бэкенд для одного процесса Node.js. Зависимости: `express@5`, `better-sqlite3`, `@telegram-apps/init-data-node`. Переменные окружения: `BOT_TOKEN`, случайный `WEBHOOK_SECRET`, публичный HTTPS-адрес `PUBLIC_URL` и целая цена `SKIN_PRICE_XTR`.

```js
import express from "express";
import Database from "better-sqlite3";
import { randomUUID } from "node:crypto";
import { validate, parse } from "@telegram-apps/init-data-node";

const { BOT_TOKEN, WEBHOOK_SECRET, PUBLIC_URL } = process.env;
const PRICE = Number(process.env.SKIN_PRICE_XTR);

if (!BOT_TOKEN || !WEBHOOK_SECRET || !PUBLIC_URL ||
    !Number.isSafeInteger(PRICE) || PRICE <= 0) {
  throw new Error("Проверьте настройки");
}

const app = express();
app.use(express.json());

const db = new Database("payments.sqlite");
db.pragma("journal_mode = WAL");
db.exec(`
  CREATE TABLE IF NOT EXISTS orders (
    id TEXT PRIMARY KEY, uid TEXT NOT NULL,
    amount INTEGER NOT NULL, paid INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS premium_skin (uid TEXT PRIMARY KEY);
  CREATE TABLE IF NOT EXISTS payments (
    charge TEXT PRIMARY KEY, uid TEXT NOT NULL,
    refund INTEGER NOT NULL DEFAULT 0
  );
`);

const one = (sql, ...args) => db.prepare(sql).get(...args);
const run = (sql, ...args) => db.prepare(sql).run(...args);
const ownsSkin = uid => !!one("SELECT 1 FROM premium_skin WHERE uid=?", uid);

async function bot(method, body) {
  const response = await fetch(
    `https://api.telegram.org/bot${BOT_TOKEN}/${method}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(5000),
    },
  );
  const result = await response.json();
  if (!result.ok) throw new Error(result.description);
  return result.result;
}

app.post("/api/skin/invoice", async (req, res) => {
  let uid;
  try {
    const raw = req.body.initData;
    validate(raw, BOT_TOKEN, { expiresIn: 3600 });
    const user = parse(raw).user;
    if (!user) throw new Error("Нет пользователя");
    uid = String(user.id);
  } catch {
    return res.sendStatus(401);
  }

  if (ownsSkin(uid)) return res.status(409).send("Скин уже куплен");

  const id = randomUUID();
  run("INSERT INTO orders(id,uid,amount) VALUES(?,?,?)", id, uid, PRICE);

  const invoiceUrl = await bot("createInvoiceLink", {
    title: "Премиум-скин",
    description: "Премиум-скин для вашего персонажа",
    payload: id,
    provider_token: "",
    currency: "XTR",
    prices: [{ label: "Премиум-скин", amount: PRICE }],
  });

  res.json({ invoiceUrl });
});

function matches(order, uid, payment) {
  return order &&
    order.uid === String(uid) &&
    payment.currency === "XTR" &&
    payment.total_amount === order.amount;
}

// Фиксация платежа и выдача скина выполняются атомарно.
const fulfill = db.transaction(message => {
  const p = message.successful_payment;
  const charge = p.telegram_payment_charge_id;

  // Повтор webhook не приводит к повторной выдаче.
  if (one("SELECT 1 FROM payments WHERE charge=?", charge)) return;

  const order = one("SELECT * FROM orders WHERE id=?", p.invoice_payload);
  if (!matches(order, message.from.id, p)) {
    throw new Error("Платёж не соответствует заказу");
  }

  const granted = run(
    "INSERT INTO premium_skin(uid) VALUES(?) ON CONFLICT(uid) DO NOTHING",
    order.uid,
  ).changes;

  // При двух параллельных покупках лишнее списание идёт на возврат.
  run(
    "INSERT INTO payments(charge,uid,refund) VALUES(?,?,?)",
    charge, order.uid, granted ? 0 : 1,
  );
  run("UPDATE orders SET paid=1 WHERE id=?", order.id);
});

app.post("/telegram", async (req, res) => {
  if (req.get("X-Telegram-Bot-Api-Secret-Token") !== WEBHOOK_SECRET) {
    return res.sendStatus(403);
  }

  const update = req.body;
  const q = update.pre_checkout_query;

  if (q) {
    const order = one("SELECT * FROM orders WHERE id=?", q.invoice_payload);
    const ok = !!(
      matches(order, q.from.id, q) &&
      !order.paid &&
      !ownsSkin(order.uid)
    );

    // Telegram ожидает ответ в течение 10 секунд.
    await bot("answerPreCheckoutQuery", {
      pre_checkout_query_id: q.id,
      ok,
      ...(ok ? {} : { error_message: "Заказ недоступен. Обновите магазин." }),
    });
  }

  if (update.message?.successful_payment) fulfill(update.message);
  res.sendStatus(200);
});

// Постоянная очередь возвратов переживает перезапуск процесса.
async function refundLoop() {
  try {
    const pending = db.prepare(
      "SELECT * FROM payments WHERE refund=1",
    ).all();

    for (const payment of pending) {
      try {
        await bot("refundStarPayment", {
          user_id: Number(payment.uid),
          telegram_payment_charge_id: payment.charge,
        });
        run("UPDATE payments SET refund=2 WHERE charge=?", payment.charge);
      } catch {
        console.error("Требует проверки возврат:", payment.charge);
      }
    }
  } finally {
    setTimeout(refundLoop, 5000).unref();
  }
}

app.use((error, req, res, next) => {
  console.error(error.message);
  res.sendStatus(500); // Telegram повторит доставку webhook.
});

app.listen(3000);
void refundLoop();

await bot("setWebhook", {
  url: new URL("/telegram", PUBLIC_URL).href,
  secret_token: WEBHOOK_SECRET,
  allowed_updates: ["message", "pre_checkout_query"],
});
```

**Основание для выдачи — серверное `successful_payment`**, проверенное по пользователю, заказу, валюте и сумме. Клиентский статус `paid` используется только для интерфейса.

Для эксплуатации добавьте `/paysupport` и мониторинг возвратов: если процесс завершится после возврата, но до записи результата, потребуется сверка с Telegram. При нескольких экземплярах сервера используйте общую БД вместо локального SQLite.
